193:         } else {
194:             if (doRetry && retryCount >= maxRetries) {
195:                 e = new RuntimeException(String.format("Number of retries reached the limit of max retries(configured value %d)", maxRetries));
196:             }
197:             if (Objects.isNull(e)) {
198:                 handleFailures(bulkRequestForRetry, bulkResponse.items());
199:             } else {
200:                 handleFailures(bulkRequestForRetry, e);
201:             }
202:             bulkRequestFailedCounter.increment();
203:         }
