209:         int retryCount = retryCountMap.get(bulkRequestForRetry);
210:         if (backOffUtils.hasNext()) {
211:             // Wait for backOff duration
212:             backOffUtils.next();
213:             final BulkResponse bulkResponse;
214:             try {
215:                 bulkResponse = requestFunction.apply(bulkRequestForRetry);
216:             } catch (Exception e) {
217:                 if (e instanceof OpenSearchException) {
218:                     int status = ((OpenSearchException) e).status();
219:                     if (NOT_ALLOWED_ERRORS.contains(status)) {
220:                         bulkRequestNotAllowedErrors.increment();
221:                     } else if (INVALID_INPUT_ERRORS.contains(status)) {
222:                         bulkRequestInvalidInputErrors.increment();
223:                     } else if (NOT_FOUND_ERRORS.contains(status)) {
224:                         bulkRequestNotFoundErrors.increment();
225:                     } else if (status == RestStatus.REQUEST_TIMEOUT.getStatus()) {
226:                         bulkRequestTimeoutErrors.increment();
227:                     } else if (status >= RestStatus.INTERNAL_SERVER_ERROR.getStatus()) {
228:                         bulkRequestServerErrors.increment();
229:                     } else { // Default to Bad Requests
230:                         bulkRequestBadErrors.increment();
231:                     }
232:                 }
233:                 handleRetriesAndFailures(bulkRequestForRetry, retryCount, backOffUtils, null, e);
